async function apply(){if(!preview||!selection)throw Error('Calcule uma prévia válida.');const label=selection.name,asset=World.from(selection),t=transform(),wasMove=!!movingId,verified=wasMove?moveObjectPreview(world,movingId,t):previewPlacement(world,asset,t);if(verified.collisions&&!$('#allow-collision').checked)throw Error('Colisão com estrutura existente.');if(!wasMove){verified.placementsBefore=structuredClone(world.placements);verified.placementsAfter=[...structuredClone(world.placements),placementRecord(world,asset,t,verified,{name:label})];}const {candidate,...op}=verified;selection=null;orbitMode();await commitOperation(op,`${wasMove?'Mover':'Construção'} ${label}`);renderAssets();updatePreview();toast(wasMove?'Construção movida sem duplicação.':'Construção e terreno aplicados juntos. Desfazer disponível.');}
