async function renderImages(){const list=$('#references');list.replaceChildren();const all=await db.all('images');images=all.filter(im=>im.floor===current+1);$('#reference-note').textContent=images.length?`${images.length} referência(s) deste andar. Uso visual; reconstrução automática por imagem ainda não implementada.`:'Adicione referências para orientar a composição. As referências originais recebidas estão disponíveis abaixo. A reconstrução detalhada do terreno permanece em desenvolvimento.';images.forEach(im=>{const btn=document.createElement('button'),image=document.createElement('img');image.src=im.url;image.alt=im.name;btn.append(image);btn.onclick=()=>{const body=document.createElement('div'),large=document.createElement('img'),p=document.createElement('p');large.src=im.url;large.alt=im.name;p.textContent=im.name;body.append(large,p);modal('Referência do andar',body);};list.append(btn);});}
async function importImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Aceitos PNG, JPEG e WebP de até 10 MB.');if(images.length>=8)throw Error('Limite de oito referências por andar neste MVP.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>20000000){bitmap.close();throw Error('Imagem excede 20 megapixels.');}const canvas=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const im={id:uid(),floor:current+1,name:file.name,url:canvas.toDataURL('image/jpeg',.86)};await db.put('images',im.id,im);await renderImages();log('Referência adicionada · '+file.name);}
