async function exportSchem(){if(!world)throw Error('Gere um terreno antes de exportar.');await saveQueue;const bytes=await gzip(encodeSchematic(world));download(bytes,`aincrad-andar-${number(current+1)}-r${world.revision}.schem`,'application/octet-stream');log(`Sponge v3 exportado · ${fmt(bytes.length)} bytes. Homologação no Minecraft pendente.`);toast('Schematic exportado. Não é uma pasta de mundo Minecraft.');}
