function statusDialog(){modal('Recursos e status',`<p>Editor local v1.0. Os dados são salvos neste navegador; nenhum servidor Minecraft está conectado.</p><div class="feature-row">Modelos e texturas vanilla 1.21.11 com Deepslate<span class="done">Implementado; especiais com fallback</span></div><div class="feature-row">Selecionar e mover construções existentes<span class="done">Objetos registrados e detecção aproximada</span></div><div class="feature-row">Dimensões X/Y/Z e tipos de terreno<span class="done">Implementado dentro das quotas</span></div><div class="feature-row">Vila, masmorra, labirinto e arena combináveis<span class="done">Módulos procedurais básicos</span></div><div class="feature-row">Cinco paisagens temáticas de Aincrad<span class="done">Visuais; datapacks na exportação de mundo</span></div><div class="feature-row">Imagens de referência, mapas externos e .schem<span class="done">Implementado com limites</span></div><div class="feature-row">Pincéis, adaptação, histórico e backup<span class="done">Implementado</span></div><div class="feature-row">Reconstrução arquitetônica por imagem em perspectiva<span>Não implementado</span></div><div class="feature-row">Mundos grandes por chunks · X/Z até 2048<span class="done">Janela 3D e gravação em disco</span></div><div class="feature-row">Andar circular, pilares e margem mínima de 1.000 blocos<span class="done">Implementado na exportação e nas prévias</span></div><div class="feature-row">Heightmap, máscara de biomas e seleção por área<span class="done">Implementado</span></div><div class="feature-row">Pasta de mundo Anvil + level.dat<span class="done">Exportação local implementada</span></div><div class="feature-row">Plugins e rede MMORPG<span>Planejado</span></div><p>X/Z 32–256, Y 48–192, até 2.097.152 posições. Blocos especiais sem modelo estático usam fallback visível. Identificação de grupos antigos é por conectividade e materiais; não reconhece perfeitamente edifícios arbitrários de pedra. Homologação em Minecraft e capacidade de mil jogadores permanecem pendentes.</p>`);}
function mmoDialog(){modal('Rede MMORPG',`<p>A infraestrutura MMORPG está planejada. Este painel não simula jogadores online, servidores ativos nem vitórias reais.</p><h3>Progressão global</h3><p>A primeira vitória elegível de um grupo deverá gravar uma conquista única no PostgreSQL e liberar o próximo andar globalmente. Demais grupos poderão repetir o boss e receber recompensas de replay. Publicação do mapa e disponibilidade de servidor serão verificadas separadamente.</p><h3>Arquitetura definida</h3><p>Velocity como entrada; Paper por canal ou arena; PostgreSQL como autoridade de personagens, conquistas e recompensas; Redis para presença e invalidação. Entrega idempotente e outbox durável evitarão duplicações.</p><h3>Antes de abrir ao público</h3><ul><li>Plugin Java com validação de combate e transferências.</li><li>Serviços autenticados e migrações de banco.</li><li>Testes de concorrência, falha e restauração.</li><li>Benchmark de 1.200 sessões distribuídas.</li></ul><p>O modelo SQL inicial e os contratos técnicos acompanham o código-fonte.</p>`);}
const packWorld=s=>s?{...s,cells:Array.from(s.cells),placements:(s.placements||[]).map(p=>({...p,asset:{...p.asset,cells:Array.from(p.asset.cells),placements:[]}}))}:null;
async function backup(){await saveQueue;const floors=await db.all('floors'),savedAssets=await db.all('assets'),images=await db.all('images');const data={format:'aincrad-project',version:1,exportedAt:new Date().toISOString(),project,floors:floors.map(f=>({id:f.id,world:packWorld(f.world)})),assets:savedAssets.map(packWorld),images};download(JSON.stringify(data),'Aincrad-World-Studio.aincrad','application/json');log('Backup do projeto exportado. Histórico não incluído no backup.');}
function validateSnapshot(s,nested=false){
 if(!s||![s.w,s.h,s.d].every(n=>Number.isInteger(n)&&n>0&&n<=512)||s.w*s.h*s.d>2097152||!Array.isArray(s.cells)||s.cells.length!==s.w*s.h*s.d||!Array.isArray(s.palette)||!s.palette.length||s.palette.length>65534||s.palette[0]!=='minecraft:air'||!s.palette.every(x=>typeof x==='string'&&/^minecraft:[a-z0-9_]+(?:\[[a-z0-9_=,]+\])?$/.test(x)&&!/command_block|structure_block|jigsaw/.test(x))||!s.cells.every(n=>Number.isInteger(n)&&n>=0&&n<s.palette.length))throw Error('Dados voxel inválidos no backup.');
 const target={...s,cells:Uint16Array.from(s.cells),revision:Number.isSafeInteger(s.revision)&&s.revision>=0?s.revision:0,placements:[]};
 if(s.placements!==undefined&&(!Array.isArray(s.placements)||s.placements.length>128||nested&&s.placements.length))throw Error('Objetos inválidos no backup.');
 const ids=new Set();for(const p of s.placements||[]){if(!p||typeof p.id!=='string'||p.id.length>100||ids.has(p.id)||!Array.isArray(p.delta)||p.delta.length>target.cells.length)throw Error('Objeto inválido no backup.');ids.add(p.id);const asset=validateSnapshot(p.asset,true),t=p.transform,width=t?.rotation%180?asset.d:asset.w,depth=t?.rotation%180?asset.w:asset.d;
  if(!t||![t.x,t.y,t.z].every(Number.isInteger)||![0,90,180,270].includes(t.rotation)||t.x<0||t.y<0||t.z<0||t.x+width>s.w||t.y+asset.h>s.h||t.z+depth>s.d)throw Error('Transformação de objeto inválida.');
  const delta=p.delta.map(c=>{if(!Number.isInteger(c.idx)||c.idx<0||c.idx>=target.cells.length||![c.before,c.after].every(v=>typeof v==='string'&&/^minecraft:[a-z0-9_]+(?:\[[a-z0-9_=,]+\])?$/.test(v)&&!/command_block|structure_block|jigsaw/.test(v)))throw Error('Histórico de objeto inválido.');return {idx:c.idx,before:c.before,after:c.after};});
  target.placements.push({id:p.id,name:String(p.name||'Construção').slice(0,100),asset,transform:{...t},delta,solidIndices:solidIndices(World.from({...target,placements:[]}),World.from(asset),t),bounds:[t.x,t.y,t.z,width,asset.h,depth],detected:!!p.detected});
 }return target;
}
async function restore(file){
 if(!file)return;if(file.size>80*1024*1024)throw Error('Backup excede 80 MiB.');const data=JSON.parse(await file.text());
 if(data.format!=='aincrad-project'||data.version!==1||!Array.isArray(data.project?.floors)||data.project.floors.length!==100||!Array.isArray(data.floors)||data.floors.length>100||!Array.isArray(data.assets)||data.assets.length>100||!Array.isArray(data.images)||data.images.length>800)throw Error('Formato de backup inválido.');
 const config=data.project.floors.map((f,i)=>{if(!Object.hasOwn(types,f.type)||typeof f.name!=='string'||f.name.length>80||typeof f.seed!=='string'||f.seed.length>64)throw Error(`Configuração inválida no andar ${i+1}.`);return {...normalizeGeneration(f),configured:false};});
 const floors=data.floors.map(f=>{if(!Number.isInteger(f.id)||f.id<1||f.id>100)throw Error('Andar inválido.');const snap=f.world?validateSnapshot(f.world):null;config[f.id-1].configured=!!snap;return {id:f.id,world:snap,history:[],future:[]};});
 if(new Set(floors.map(f=>f.id)).size!==floors.length)throw Error('Andar duplicado.');
 const restoredAssets=data.assets.map(a=>{const s=validateSnapshot(a);return {...s,id:uid(),name:String(a.name||'Construção').slice(0,100),builtin:false,format:a.format===2?2:3,sourceKind:a.sourceKind==='map'?'map':undefined,sourceName:String(a.sourceName||'').slice(0,200),offset:Array.isArray(a.offset)&&a.offset.length===3&&a.offset.every(Number.isSafeInteger)?a.offset:[0,0,0]};});
 const restoredImages=data.images.map(im=>{if(!Number.isInteger(im.floor)||im.floor<1||im.floor>100||typeof im.url!=='string'||im.url.length>5000000||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(im.url))throw Error('Imagem inválida no backup.');return {id:uid(),floor:im.floor,name:String(im.name||'Referência').slice(0,100),url:im.url};});
 await db.replaceProject({version:1,active:0,floors:config},floors,restoredAssets,restoredImages);location.reload();
}
function projectDialog(){modal('Seu projeto',`<p>Salvamento automático neste navegador. Faça um backup para guardar uma cópia ou transferir o projeto. O arquivo contém todos os andares gerados, construções e referências; o histórico de desfazer fica no navegador.</p><div class="dialog-actions"><button id="download-project" class="button primary">↓ Baixar backup completo</button><button id="restore-project" class="button secondary">↑ Restaurar backup</button></div><p>Restaurar substitui o projeto local inteiro. Baixe um backup antes. A importação valida todos os dados antes da troca.</p>`);$('#download-project').onclick=()=>run(backup);$('#restore-project').onclick=()=>{if(confirm('Restaurar um backup substituirá o projeto local. Você já guardou uma cópia?'))$('#project-file').click();};}
async function init(){
 try{await loadMinecraftResources();log('Modelos e texturas Minecraft 1.21.11 carregados · Deepslate.');}catch(e){log('Renderização simplificada: '+e.message,'warning');}
 renderer=new Renderer($('#scene'),point=>pickSceneObject(point));
 brushEditor=createBrushEditor({getWorld:()=>world,getRenderer:()=>renderer,isBusy:()=>busy,activate:()=>{selection=null;movingId=null;clearTimeout(previewTimer);renderAssets();setInspector('brush');drawWorld();$('#orbit').classList.remove('selected');$('#brush-tool').classList.add('selected');toolTip('brush');},restore:()=>drawWorld(),onError:e=>{log(e.message,'warning');toast(e.message);},onHint:editHint,commit:async op=>{if(busy)throw Error('Aguarde a operação atual.');busy=true;document.body.classList.add('busy');try{await commitOperation(op,op.label);}finally{busy=false;document.body.classList.remove('busy');}}});
 project=await db.get('meta','project');const fresh=!project;
 if(!project){project={version:1,active:0,floors:Array.from({length:100},(_,i)=>({name:i===0?'O início da jornada':`Andar ${number(i+1)}`,type:'island',seed:`aincrad-${number(i+1)}`,size:80,relief:7,configured:i===0}))};world=generate(project.floors[0]);await saveFloor();await saveMeta();}
 current=Number.isInteger(project.active)&&project.active>=0&&project.active<100?project.active:0;
 const record=await db.get('floors',current+1);world=record?.world?World.from(record.world):null;if(world){$('#cut').max=world.h;$('#cut').value=world.h;}history=record?.history||[];future=record?.future||[];
 assets=[{...house().snapshot(),id:'builtin-house',name:'Casa medieval',builtin:true},{...tower().snapshot(),id:'builtin-tower',name:'Torre de vigia',builtin:true},...await db.all('assets')];
 renderFloors();renderProperties();renderAssets();await renderImages();drawWorld();if(world)renderer.reset();log(fresh?'Projeto criado. Cena inicial procedural; referências originais disponíveis no painel.':'Projeto recuperado do armazenamento local.');
}
